import{_ as l,c as o,o as a,ag as n}from"./chunks/framework.DfL_BkQ-.js";const f=JSON.parse('{"title":"Привилегии","description":"","frontmatter":{},"headers":[],"relativePath":"info/ranks.md","filePath":"info/ranks.md"}'),t={name:"info/ranks.md"};function e(r,s,p,i,c,y){return a(),o("div",null,[...s[0]||(s[0]=[n('<h1 id="привилегии" tabindex="-1">Привилегии <a class="header-anchor" href="#привилегии" aria-label="Permalink to &quot;Привилегии&quot;">​</a></h1><blockquote><p>Проект <strong>Manima</strong> разрабатывается на чистом энтузиазме и в свободное время. Помимо оплаты оборудования и поддержания работы технической части, нам необходимо покупать рекламу и плагины. Также наша команда берёт на себя все задачи, связанные с предоставлением комфортного сервера, увлекательного геймплея и формирования уютного сообщества.</p></blockquote><blockquote><p>В случаях, если наш проект вызывает интерес и может порадовать даже самого бывалого игрока, мы принимаем <strong>пожертвования</strong> и <strong>финансовую безвозмездную помощь</strong>. Каждый пользователь, который поддержал развитие сервера, будет вознаграждён одной из проработанных привилегий, дабы подчеркнуть его важность и статус на проекте.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">Важно</p><p>Обязательно ознакомьтесь с пунктом правил <strong>№9</strong> на <a href="/rules/#_9-дополнительная-информация">странице правил</a>.</p></div><blockquote><p><strong>Наш магазин</strong> — <a href="https://shop.manima.ru/" target="_blank" rel="noreferrer">https://shop.manima.ru/</a></p></blockquote><h2 id="▌-привилегия-unique" tabindex="-1"><span style="color:#3b82f6;">▌ Привилегия Unique</span> <a class="header-anchor" href="#▌-привилегия-unique" aria-label="Permalink to &quot;&lt;span style=&quot;color: #3b82f6&quot;&gt;▌ Привилегия Unique&lt;/span&gt;&quot;">​</a></h2><p>⭐⚫⚫⚫</p><blockquote><p>На 1 месяц — <strong>249р.</strong></p></blockquote><details class="details custom-block"><summary><span style="color:#3b82f6;">Возможности привилегии (Нажмите, чтобы открыть)</span></summary><p>Обязательно ознакомьтесь с доступными командами привилегии на сервере через <span style="color:#3b82f6;">/unique</span>.</p><ul><li>Дополнительные <span style="color:#3b82f6;"><strong>5Ⓜ</strong></span> за 10 минут игры</li><li>Открыть верстак <span style="color:#3b82f6;">/workbench</span></li><li>Открыть мусорку <span style="color:#3b82f6;">/dispose</span></li><li>Телепорт к партнеру <span style="color:#3b82f6;">/marry tp</span></li><li>Узнать когда игрок был в сети <span style="color:#3b82f6;">/seen</span></li><li>Флаги привата: <span style="color:#3b82f6;">fire-spread</span>, <span style="color:#3b82f6;">tnt</span>, <span style="color:#3b82f6;">creeper-explosion</span>, <span style="color:#3b82f6;">ravager-grief</span>, <span style="color:#3b82f6;">enderman-grief</span></li><li>Доступно <span style="color:#3b82f6;"><strong>7</strong></span> слотов на аукционе</li><li>Доступ к созданию <span style="color:#3b82f6;"><strong>3-х</strong></span> точек дома</li><li>Возможность приватить <span style="color:#3b82f6;"><strong>2</strong></span> региона</li><li>Улучшенная <span style="color:#3b82f6;"><strong>ежедневная</strong></span> награда</li><li>Префикс <span style="color:#3b82f6;"><strong>ᴜɴɪǫᴜᴇ</strong></span> перед ником</li><li>Уникальный комплект <span style="color:#3b82f6;">/kit unique</span></li></ul><p><em>Осмотреть уникальный набор для привилегии можно на самом сервере.</em></p></details><h2 id="▌-привилегия-heroic" tabindex="-1"><span style="color:#a855f7;">▌ Привилегия Heroic</span> <a class="header-anchor" href="#▌-привилегия-heroic" aria-label="Permalink to &quot;&lt;span style=&quot;color: #a855f7&quot;&gt;▌ Привилегия Heroic&lt;/span&gt;&quot;">​</a></h2><p>⭐⭐⚫⚫</p><blockquote><p>На 1 месяц — <strong>499р.</strong></p></blockquote><details class="details custom-block"><summary><span style="color:#a855f7;">Возможности привилегии (Нажмите, чтобы открыть)</span></summary><p>Обязательно ознакомьтесь с доступными командами привилегии на сервере через <span style="color:#a855f7;">/heroic</span>.</p><ul><li>Дополнительные <span style="color:#a855f7;"><strong>5Ⓜ</strong></span> за 10 минут игры</li><li>Создание <span style="color:#a855f7;"><strong>2-х</strong></span> личных магазинов</li><li>Надеть блок на голову <span style="color:#a855f7;">/hat</span></li><li>Открыть эндер-сундук <span style="color:#a855f7;">/ec</span></li><li>Уйти в афк <span style="color:#a855f7;">/afk</span></li><li>Узнать кто рядом в радиусе 200 блоков <span style="color:#a855f7;">/near</span></li><li>Показать коды стандартных цветов <span style="color:#a855f7;">/colors</span></li><li>Потушить себя во время горения <span style="color:#a855f7;">/ext</span></li><li>Флаги привата: <span style="color:#a855f7;">chorus-fruit-teleport</span>, <span style="color:#a855f7;">interact</span>, <span style="color:#a855f7;">use</span>, <span style="color:#a855f7;">chest-access</span>, <span style="color:#a855f7;">crop-growth</span>, <span style="color:#a855f7;">ice-form</span>, <span style="color:#a855f7;">ice-melt</span>, <span style="color:#a855f7;">leaf-decay</span>, <span style="color:#a855f7;">snow-melt</span></li><li>Доступно <span style="color:#a855f7;"><strong>10</strong></span> слотов на аукционе</li><li>Доступ к созданию <span style="color:#a855f7;"><strong>4-х</strong></span> точек дома</li><li>Возможность приватить <span style="color:#a855f7;"><strong>3</strong></span> региона</li><li>Улучшенная <span style="color:#a855f7;"><strong>ежедневная</strong></span> награда</li><li>Префикс <span style="color:#a855f7;"><strong>ʜᴇʀᴏɪᴄ</strong></span> перед ником</li><li>Героический комплект <span style="color:#a855f7;">/kit heroic</span></li></ul><p><span style="color:#22c55e;"><strong>+</strong></span> Включает все возможности привилегии Unique.</p><p><em>Осмотреть уникальный набор для привилегии можно на самом сервере.</em></p></details><h2 id="▌-привилегия-mythic" tabindex="-1"><span style="color:#eab308;">▌ Привилегия Mythic</span> <a class="header-anchor" href="#▌-привилегия-mythic" aria-label="Permalink to &quot;&lt;span style=&quot;color: #eab308&quot;&gt;▌ Привилегия Mythic&lt;/span&gt;&quot;">​</a></h2><p>⭐⭐⭐⚫</p><blockquote><p>На 1 месяц — <strong>799р.</strong></p></blockquote><details class="details custom-block"><summary><span style="color:#eab308;">Возможности привилегии (Нажмите, чтобы открыть)</span></summary><p>Обязательно ознакомьтесь с доступными командами привилегии на сервере через <span style="color:#eab308;">/mythic</span>.</p><ul><li>Дополнительные <span style="color:#eab308;"><strong>5Ⓜ</strong></span> за 10 минут игры</li><li>Создание <span style="color:#eab308;"><strong>4-х</strong></span> личных магазинов</li><li>Сесть на любую сущность <span style="color:#eab308;">/ride</span></li><li>Открыть камнерез <span style="color:#eab308;">/stonecutter</span></li><li>Открыть ткацкий станок <span style="color:#eab308;">/loom</span></li><li>Открыть точило <span style="color:#eab308;">/grindstone</span></li><li>Заряд полёта (1000 ед.) <span style="color:#eab308;">/flyc</span></li><li>Телепорт по направлению взгляда <span style="color:#eab308;">/jump</span></li><li>Флаги привата: <span style="color:#eab308;">enderpearl</span>, <span style="color:#eab308;">wither-damage</span>, <span style="color:#eab308;">coral-fade</span>, <span style="color:#eab308;">greeting</span>, <span style="color:#eab308;">greeting-title</span>, <span style="color:#eab308;">farewell</span>, <span style="color:#eab308;">farewell-title</span>, <span style="color:#eab308;">mob-spawning</span>, <span style="color:#eab308;">vine-growth</span></li><li>Доступно <span style="color:#eab308;"><strong>15</strong></span> слотов на аукционе</li><li>Доступ к созданию <span style="color:#eab308;"><strong>5</strong></span> точек дома</li><li>Возможность приватить <span style="color:#eab308;"><strong>4</strong></span> региона</li><li>Улучшенная <span style="color:#eab308;"><strong>ежедневная</strong></span> награда</li><li>Префикс <span style="color:#eab308;"><strong>ᴍʏᴛʜɪᴄ</strong></span> перед ником</li><li>Мифический комплект <span style="color:#eab308;">/kit mythic</span></li></ul><p><span style="color:#22c55e;"><strong>+</strong></span> Включает все возможности привилегий ниже.</p><p><em>Осмотреть уникальный набор для привилегии можно на самом сервере.</em></p></details><h2 id="▌-привилегия-cosmic" tabindex="-1"><span style="color:#ef4444;">▌ Привилегия Cosmic</span> <a class="header-anchor" href="#▌-привилегия-cosmic" aria-label="Permalink to &quot;&lt;span style=&quot;color: #ef4444&quot;&gt;▌ Привилегия Cosmic&lt;/span&gt;&quot;">​</a></h2><p>⭐⭐⭐⭐</p><blockquote><p>На 1 месяц — <strong>1199р.</strong></p></blockquote><details class="details custom-block"><summary><span style="color:#ef4444;">Возможности привилегии (Нажмите, чтобы открыть)</span></summary><p>Обязательно ознакомьтесь с доступными командами привилегии на сервере через <span style="color:#ef4444;">/cosmic</span>.</p><ul><li>Дополнительные <span style="color:#ef4444;"><strong>5Ⓜ</strong></span> за 10 минут игры</li><li>Дополнительные <span style="color:#a855f7;"><strong>1Ⓟ</strong></span> за 10 минут игры</li><li>Создание <span style="color:#ef4444;"><strong>6-ти</strong></span> личных магазинов</li><li>Пополнить полоску жизни <span style="color:#ef4444;">/heal</span></li><li>Пополнить полоску голода <span style="color:#ef4444;">/feed</span></li><li>Вернуться назад <span style="color:#ef4444;">/back</span></li><li>Вернуться на точку смерти <span style="color:#ef4444;">/dback</span></li><li><span style="color:#ef4444;"><strong>Увеличенный</strong></span> заряд полёта (7000 ед.)</li><li>Купить заряд полёта (1 ед. к 1Ⓜ) <span style="color:#ef4444;">/recharge</span></li><li>Доступно <span style="color:#ef4444;"><strong>20</strong></span> слотов на аукционе</li><li>Доступ к созданию <span style="color:#ef4444;"><strong>6</strong></span> точек дома</li><li>Возможность приватить <span style="color:#ef4444;"><strong>5</strong></span> регионов</li><li>Улучшенная <span style="color:#ef4444;"><strong>ежедневная</strong></span> награда</li><li>Префикс <span style="color:#ef4444;"><strong>ᴄᴏsᴍɪᴄ</strong></span> перед ником</li><li>Космический комплект <span style="color:#ef4444;">/kit cosmic</span></li></ul><p><span style="color:#22c55e;"><strong>+</strong></span> Включает все возможности привилегий ниже.</p><p><em>Осмотреть уникальный набор для привилегии можно на самом сервере.</em></p></details>',21)])])}const b=l(t,[["render",e]]);export{f as __pageData,b as default};
